} as const;

export type PrimitiveShadow = keyof typeof primitiveShadow;

// ─── Transition ───────────────────────────────────────────────────────────────

/**
 * Primitive transition tokens — aligned with the four-rail motion scale
 * (SSOT: @nebutra/design-tokens core.json → duration.*).
 * Keys mirror semantic.json motion.duration.*; values are in ms.
 */
export const primitiveTransition = {
  duration: {
    micro: 100, // hover, focus, small state changes
    flow: 200, // standard state transitions (default)
    reveal: 300, // larger motion (accordion, modal, drawer)
    cinematic: 500, // hero entrance, big delight moments
  },
  easing: {
    default: "ease-out",
    spring: "cubic-bezier(0.34, 1.56, 0.64, 1)",
    inOut: "cubic-bezier(0.4, 0, 0.2, 1)",
  },
} as const;

// ─── Focus Ring ───────────────────────────────────────────────────────────────

export const primitiveFocusRing = {
  width: 2, // px
  offset: 2, // px — gap between element and ring
} as const;

import type * as React from "react";

export type PrimitiveProps<T> = React.PropsWithChildren<T & { className?: string | undefined }>;

export type PrimitiveComponent<TElement, TProps> = React.ForwardRefExoticComponent<
  PrimitiveProps<TProps> & React.RefAttributes<TElement>
>;

/**
 * Resolve the HTMLElement type for a given intrinsic element tag.
 */
type ElementForTag<E extends keyof React.JSX.IntrinsicElements> = E extends "button"
  ? HTMLButtonElement
  : E extends "span"
    ? HTMLSpanElement
    : E extends "img"
      ? HTMLImageElement
      : E extends "label"
        ? HTMLLabelElement
        : E extends "input"
          ? HTMLInputElement
          : E extends "a"
            ? HTMLAnchorElement
            : E extends "p"
              ? HTMLParagraphElement
              : E extends "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
                ? HTMLHeadingElement
                : HTMLElement;

/**
 * Workaround for Radix UI types not resolving HTML element props (className,
 * children, etc.) with React 19 + exactOptionalPropertyTypes.
 *
 * The optional second type parameter `Extra` allows preserving Radix-specific
 * props (e.g. `asChild`, `align`, `sideOffset`) that are not standard HTML attrs.
 *
 * Usage:
 *   const Header = withHtmlProps<"h3">(AccordionPrimitive.Header);
 *   const Trigger = withHtmlProps<"button", { asChild?: boolean }>(DialogPrimitive.Trigger);
 *   const Content = withHtmlProps<"div", { align?: string; sideOffset?: number }>(PopoverPrimitive.Content);
 */

export function withHtmlProps<E extends keyof React.JSX.IntrinsicElements, Extra = object>(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  Component: any,
): React.ForwardRefExoticComponent<
  React.ComponentPropsWithoutRef<E> & Extra & React.RefAttributes<ElementForTag<E>>
> {
  return Component;
}

"use client";

import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import * as React from "react";

import { overlayClassNames, overlayZIndex } from "../tokens/components/overlay";
import { cn } from "../utils/cn";

/* -------------------------------------------------------------------------- *\
 *  Tooltip — Base UI tooltip wrapper, used across the design system.
 *
 *  Geist behavior contract (verified in this wrapper, document at top so
 *  drift gets called out at code review):
 *    - Opens on hover AND keyboard focus (Base UI default — don't override).
 *    - Default entry delay ≈ 150ms so the tooltip doesn't flicker on a
 *      sweeping mouse. Provider-level default set below; caller can override.
 *    - Escape closes the tooltip and returns focus to the trigger (Base UI).
 *
 *  Content rules (Geist):
 *    - Explains *why* something exists, not *what* it is. The visible label
 *      names the thing; the tooltip adds the constraint, scope, or limit.
 *    - One sentence or fragment, sentence case, no terminal period for a
 *      single fragment.
 *    - Don't repeat the visible label (`text="Rate Limit"` on a Rate Limit
 *      button) and don't describe the interaction (`"Click to override"`).
 *    - Lifecycle tooltips: `{Label}: {one-line meaning}. {Specific limit}.`
 *
 *  Don'ts (caller responsibility):
 *    - Don't wrap a labelled Input in a Tooltip — the trigger lands on the
 *      <label>, not the field, and the body becomes a phantom second label.
 *      Put help on a sibling icon button instead.
 *    - Keep primary actions outside the Tooltip; touch users can't reach a
 *      hover-revealed control.
 *    - Icon-only triggers MUST carry their own `aria-label` naming the
 *      action — the tooltip body adds context, it doesn't replace the label.
\* -------------------------------------------------------------------------- */

// Geist-standard delay; matches the platform Best Practices.
const DEFAULT_TOOLTIP_DELAY_MS = 150;

// We expose Base UI's native Provider to pass global `delayDuration` downwards.
// Default landed at 150ms so isolated `<Tooltip>` usage matches Geist out of
// the box — explicit callers can still override per provider scope.
const TooltipProvider = ({
  children,
  delayDuration = DEFAULT_TOOLTIP_DELAY_MS,
}: {
  children: React.ReactNode;
  delayDuration?: number;
}) => {
  return <BaseTooltip.Provider delay={delayDuration}>{children}</BaseTooltip.Provider>;
};

const Tooltip = ({
  delayDuration,
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseTooltip.Root> & {
  delayDuration?: number;
  children?: React.ReactNode;
}) => {
  // Standalone `<Tooltip>` (no enclosing Provider) gets the Geist default;
  // any explicit `delayDuration` wins.
  const delay = delayDuration ?? DEFAULT_TOOLTIP_DELAY_MS;
  return (
    <BaseTooltip.Provider delay={delay}>
      <BaseTooltip.Root {...props}>{children}</BaseTooltip.Root>
    </BaseTooltip.Provider>
  );
};

const TooltipTrigger = ({
  asChild,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseTooltip.Trigger> & { asChild?: boolean } & {
  ref?: React.Ref<HTMLButtonElement> | undefined;
}) => {
  if (asChild && React.isValidElement(children)) {
    return (
      <BaseTooltip.Trigger
        ref={ref}
        {...props}
        render={children as React.ReactElement<Record<string, unknown>>}
      />
    );
  }
  return (
    <BaseTooltip.Trigger ref={ref} {...props}>
      {children}
    </BaseTooltip.Trigger>
  );
};
TooltipTrigger.displayName = "TooltipTrigger";

const TooltipContent = ({
  className,
  style,
  side = "top",
  align = "center",
  sideOffset = 4,
  alignOffset = 0,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseTooltip.Popup> & {
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
  sideOffset?: number;
  alignOffset?: number;
} & { ref?: React.Ref<React.ElementRef<typeof BaseTooltip.Popup>> | undefined }) => (
  <BaseTooltip.Portal>
    <BaseTooltip.Positioner
      side={side}
      align={align}
      sideOffset={sideOffset}
      alignOffset={alignOffset}
      style={{ zIndex: overlayZIndex.tooltip }}
    >
      <BaseTooltip.Popup
        ref={ref}
        className={cn(overlayClassNames.tooltipSurface, className)}
        style={{ zIndex: overlayZIndex.tooltip, ...style }}
        {...props}
      />
    </BaseTooltip.Positioner>
  </BaseTooltip.Portal>
);
TooltipContent.displayName = "TooltipContent";

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
